___CSS_LOADER_EXPORT___.push([module.id, "\n.el-select-dropdown {\n    max-width: 80% !important;\n    margin-right: 5% !important;\n}\n", "",{"version":3,"sources":["webpack://./modules/Inventory/Resources/assets/js/devolutions/partials/item.vue"],"names":[],"mappings":";AAiGA;IACA,yBAAA;IACA,2BAAA;AACA","sourcesContent":["<template>\n    <el-dialog :title=\"titleDialog\" :visible=\"showDialog\" @open=\"create\" @close=\"close\" top=\"7vh\"\n               :close-on-click-modal=\"false\">\n        <form autocomplete=\"off\" @submit.prevent=\"clickAddItem\">\n            <div class=\"form-body\">\n                <div class=\"row\">\n                    <div class=\"col-md-6 col-lg-6 col-xl-6 col-sm-6\">\n                        <div class=\"form-group\" id=\"custom-select\" :class=\"{'has-danger': errors.item_id}\">\n                            <label class=\"control-label\">\n                                Producto\n                            </label>\n\n                            <el-input id=\"custom-input\">\n                                <el-select\n                                    v-model=\"form.item_id\"\n                                    @change=\"changeItem\"\n                                    filterable\n                                    remote\n                                    placeholder=\"Buscar\"\n                                    popper-class=\"el-select-items\"\n                                    slot=\"prepend\"\n                                    id=\"select-width\"\n                                    :remote-method=\"searchRemoteItems\"\n                                    :loading=\"loading_search\">\n                                    <el-option v-for=\"option in items\" :key=\"option.id\" :value=\"option.id\"\n                                               :label=\"option.full_description\"></el-option>\n                                </el-select>\n                            </el-input>\n                        </div>\n                    </div>\n\n                    <div class=\"col-md-3 col-sm-3\">\n                        <div class=\"form-group\" :class=\"{'has-danger': errors.quantity}\">\n\n                            <label class=\"control-label\">Cantidad</label>\n                            <el-input v-model=\"form.quantity\" :disabled=\"form.item.calculate_quantity\"\n                                      @blur=\"validateQuantity\">\n                                <el-button slot=\"prepend\" icon=\"el-icon-minus\" @click=\"clickDecrease\"\n                                           :disabled=\"form.quantity < 0.01 || form.item.calculate_quantity\"></el-button>\n                                <el-button slot=\"append\" icon=\"el-icon-plus\" @click=\"clickIncrease\"\n                                           :disabled=\"form.item.calculate_quantity\"></el-button>\n                            </el-input>\n                            <small class=\"form-control-feedback\" v-if=\"errors.quantity\"\n                                   v-text=\"errors.quantity[0]\"></small>\n\n                        </div>\n                    </div>\n\n<!--                    <div style=\"padding-top: 1%;\" class=\"col-md-3 col-sm-3 mt-3\"-->\n<!--                         v-if=\"form.item_id && form.item.lots_enabled && form.lots_group.length > 0\">-->\n<!--                        <a href=\"#\" class=\"text-center font-weight-bold text-info\" @click.prevent=\"clickLotGroup\">[&#10004;-->\n<!--                            Seleccionar lote]</a>-->\n<!--                    </div>-->\n\n                    <div class=\"col-md-4 mt-4\" v-if=\"form.item_id && form.item.lots_enabled\">\n                        <a href=\"#\"  class=\"text-center font-weight-bold text-info\" @click.prevent=\"clickLotGroup\">[&#10004; Seleccionar lotes]</a>\n                    </div>\n                    <div style=\"padding-top: 1%;\" class=\"col-md-3 col-sm-3 mt-3\"\n                         v-if=\"form.item_id && form.item.series_enabled\">\n                        <a href=\"#\" class=\"text-center font-weight-bold text-info\" @click.prevent=\"clickSelectLots\">[&#10004;\n                            Seleccionar series]</a>\n                    </div>\n\n\n                </div>\n            </div>\n            <div class=\"form-actions text-right pt-2\">\n                <el-button @click.prevent=\"close()\">Cerrar</el-button>\n                <el-button class=\"add\" type=\"primary\" native-type=\"submit\" v-if=\"form.item_id\">{{ titleAction }}\n                </el-button>\n            </div>\n        </form>\n\n        <lots-group\n            :showDialog.sync=\"showDialogLots\"\n            :itemId=\"form.item_id\"\n            :lots-group-all=\"lotsGroupAll\"\n            :lots_group=\"form.lots_group\"\n            :quantity=\"form.quantity\"\n            @addRowLotGroup=\"addRowLotGroup\"\n            :compromise-all-quantity=\"true\">\n        </lots-group>\n\n\n        <select-lots-form\n            :showDialog.sync=\"showDialogSelectLots\"\n            :lots=\"lots\"\n            :itemId=\"form.item_id\"\n            :documentItemId=\"form.document_item_id\"\n            :quantity=\"form.quantity\"\n            @addRowSelectLot=\"addRowSelectLot\">\n        </select-lots-form>\n\n\n    </el-dialog>\n</template>\n<style>\n.el-select-dropdown {\n    max-width: 80% !important;\n    margin-right: 5% !important;\n}\n</style>\n\n<script>\n\n//import LotsGroup from './lots_group.vue'\n// import SelectLotsForm from '@views/documents/partials/lots.vue'\nimport LotsGroup from '../../../../../../../resources/js/views/tenant/documents/partials/lots_group';\nimport SelectLotsForm from '../../../../../../../resources/js/views/tenant/documents/partials/lots.vue';\n\nexport default {\n    props: ['showDialog'],\n    components: {LotsGroup, SelectLotsForm},\n    data() {\n        return {\n            loading_search: false,\n            titleAction: '',\n            titleDialog: '',\n            resource: 'devolutions',\n            errors: {},\n            form: {},\n            all_items: [],\n            items: [],\n            showDialogLots: false,\n            showDialogSelectLots: false,\n            lots: [],\n            lotsGroupAll: []\n        }\n    },\n    async created() {\n\n        await this.initForm()\n        await this.reloadDataItems()\n        this.$eventHub.$on('reloadDataItems', () => {\n            this.reloadDataItems()\n        })\n    },\n    methods: {\n        async reloadDataItems() {\n\n            await this.$http.get(`/${this.resource}/item/tables`).then(response => {\n                // this.items = response.data.items\n                this.all_items = response.data.items\n                this.filterItems()\n\n            })\n\n        },\n        async searchRemoteItems(input) {\n\n            if (input.length > 1) {\n\n                this.loading_search = true\n                let parameters = `input=${input}`\n\n                await this.$http.get(`/${this.resource}/search-items?${parameters}`)\n                    .then(response => {\n\n                        this.items = response.data.items\n                        this.loading_search = false\n\n                        if (this.items.length == 0) {\n                            this.filterItems()\n                        }\n                    })\n            } else {\n                await this.filterItems()\n            }\n\n        },\n        filterItems() {\n            this.items = this.all_items\n        },\n        initForm() {\n            this.errors = {};\n\n            this.form = {\n                item_id: null,\n                item: {},\n                quantity: 1,\n                lots_group: [],\n                IdLoteSelected: null,\n            };\n\n        },\n        async create() {\n\n            this.titleDialog = ' Agregar Producto';\n            this.titleAction = ' Agregar';\n        },\n        close() {\n            this.initForm()\n            this.$emit('update:showDialog', false)\n        },\n        async changeItem() {\n\n            this.form.item = _.find(this.items, {'id': this.form.item_id});\n            this.lots = this.form.item.lots\n\n            this.form.quantity = 1;\n            this.cleanTotalItem();\n\n            this.lotsGroupAll = this.form.item.lots_group\n\n        },\n        cleanTotalItem() {\n            this.total_item = null\n        },\n        async clickAddItem() {\n\n            this.validateQuantity()\n\n            if (this.form.item.lots_enabled) {\n                if (!this.form.lots_group)\n                    return this.$message.error('Debe seleccionar un lote.');\n            }\n\n            let IdLoteSelected = this.form.IdLoteSelected\n\n            let select_lots = await _.filter(this.form.item.lots, {'has_sale': true})\n            let un_select_lots = await _.filter(this.form.item.lots, {'has_sale': false})\n\n            // console.log(select_lots.length)\n\n            if (this.form.item.series_enabled) {\n                if (select_lots.length != this.form.quantity)\n                    return this.$message.error('La cantidad de series seleccionadas son diferentes a la cantidad a vender');\n            }\n\n            if (IdLoteSelected) {\n                this.form.item.lot_selected = await _.find(this.form.lots_group, {id: IdLoteSelected, checked: true})\n            }\n\n            // this.form.IdLoteSelected = IdLoteSelected\n            // this.form.IdLoteSelected = null;\n            this.$emit('add', this.form);\n\n            this.initForm();\n\n        },\n        addRowLotGroup(id) {\n            // console.log(id);\n            this.form.lots_group = id\n        },\n        clickLotGroup() {\n            this.showDialogLots = true\n        },\n        async clickSelectLots() {\n            this.showDialogSelectLots = true\n        },\n        addRowSelectLot(lots) {\n            this.lots = lots\n        },\n        validateQuantity() {\n\n            if (!this.form.quantity) {\n                this.setMinQuantity()\n            }\n\n            if (isNaN(Number(this.form.quantity))) {\n                this.setMinQuantity()\n            }\n\n            if (typeof parseFloat(this.form.quantity) !== 'number') {\n                this.setMinQuantity()\n            }\n\n            if (this.form.quantity <= this.getMinQuantity()) {\n                this.setMinQuantity()\n            }\n            // console.log(isNaN(Number(this.form.quantity)))\n        },\n        getMinQuantity() {\n            return 0.01\n        },\n        setMinQuantity() {\n            this.form.quantity = this.getMinQuantity()\n        },\n        clickDecrease() {\n\n            this.form.quantity = parseInt(this.form.quantity - 1)\n\n            if (this.form.quantity <= this.getMinQuantity()) {\n                this.setMinQuantity()\n                return\n            }\n\n        },\n        clickIncrease() {\n            this.form.quantity = parseInt(this.form.quantity + 1)\n        },\n    }\n}\n\n</script>\n"],"sourceRoot":""}]);
